import process from "node:process";
export const SIGNAL_EXIT_CODES = {
    SIGINT: 130,
    SIGTERM: 143,
};
export const GRACEFUL_SHUTDOWN_TIMEOUT_MS = 60000;
export const COMMAND_TERMINATION_GRACE_MS = 5000;
const exitCodeForSignal = (signal) => SIGNAL_EXIT_CODES[signal] ?? 1;
export const notifySignals = (signals = ["SIGINT", "SIGTERM"], onRepeat) => {
    const controller = new AbortController();
    let info;
    const handler = (signal) => {
        if (info) {
            onRepeat?.(signal);
            return;
        }
        const receivedAt = Date.now();
        info = {
            signal,
            code: exitCodeForSignal(signal),
            receivedAt,
            deadline: receivedAt + GRACEFUL_SHUTDOWN_TIMEOUT_MS,
        };
        controller.abort();
    };
    for (const signal of signals) {
        process.on(signal, handler);
    }
    return {
        signal: controller.signal,
        info: () => info,
        dispose: () => {
            for (const signal of signals) {
                process.off(signal, handler);
            }
        },
    };
};
export const gracefulShutdownRemaining = (info) => {
    if (!info) {
        return undefined;
    }
    return Math.max(0, info.deadline - Date.now());
};
export const boundedTerminationSignal = (info, graceMs = COMMAND_TERMINATION_GRACE_MS) => {
    const remaining = gracefulShutdownRemaining(info);
    const timeoutMs = remaining === undefined ? graceMs : Math.min(remaining, graceMs);
    return AbortSignal.timeout(timeoutMs);
};
export const waitForAbort = (signal) => signal.aborted
    ? Promise.resolve()
    : new Promise((resolve) => signal.addEventListener("abort", () => resolve(), { once: true }));
